const express = require('express');
const { EventStoreDBClient, START } = require('@eventstore/db-client');
const { requireStaffAuth } = require('../auth');
const { db } = require('../db');

const router = express.Router();
const client = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URL);

router.get('/api/queries/patients/:patientId/history', requireStaffAuth, async (req, res) => {
  const { patientId } = req.params;

  const assignment = await db.query(
    'SELECT id FROM staff_patient_assignments WHERE staff_id = $1 AND patient_id = $2',
    [req.staff.id, patientId]
  );
  if (!assignment.rows.length && !req.staff.isMedicalDirector) {
    return res.status(403).json({ error: 'Access denied to patient clinical history stream' });
  }

  const events = [];
  const stream = client.readStream(`patient-${patientId}`, { fromRevision: START });
  for await (const resolvedEvent of stream) {
    events.push(resolvedEvent.event.data);
  }

  res.json({ patientId, historyEvents: events });
});
